import math
def control(obs):
    h=obs['hitch_deg']
    pts=[]
    for view in obs.get('views',{}).values():
        if not isinstance(view,dict): continue
        ox,oy=view.get('origin',[0,0])
        for b,d in view.get('walls',[]):
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            if -13<x<-6 and abs(y)<8: pts.append((x,y))
    left=[y for x,y in pts if y>0]; right=[y for x,y in pts if y<0]
    desired=0
    if left and right:
        center=(sum(left)/len(left)+sum(right)/len(right))/2
        desired=max(-8,min(8,center*4))
    return (max(-25,min(25,1.8*(h-desired))),-0.5,170)

